import requests
import re
import urllib.parse
import json
import base64
import concurrent.futures
import urllib3

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def run_scraper():
    ip = "__TARGET_IP__"
    req_path = "__TARGET_PATH__"
    method = "__TARGET_METHOD__"
    req_data_b64 = "__TARGET_DATA__"

    session_attr = f"_web_setting_session_{ip.replace('.', '_')}"
    session = getattr(bridge, session_attr, None)
    if not session:
        session = requests.Session()
        session.verify = False
        session.headers.update({"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"})
        setattr(bridge, session_attr, session)

    base_url = f"http://{ip}"
    is_ricoh = False

    # Try HTTP first, fallback to HTTPS if HTTP fails
    try:
        probe = session.get(base_url, timeout=4)
        is_ricoh = "ricoh" in probe.headers.get("Server", "").lower() or "web image monitor" in probe.text.lower()
    except Exception:
        base_url = f"https://{ip}"
        try:
            probe = session.get(base_url, timeout=4)
            is_ricoh = "ricoh" in probe.headers.get("Server", "").lower() or "web image monitor" in probe.text.lower()
        except Exception:
            # Fallback to http so connection error is reported normally
            base_url = f"http://{ip}"

    # Try to resolve registered printer credentials from bridge database context
    target_user = "admin"
    target_pass = ""
    try:
        printers = bridge._load_printers()
        for p in printers:
            if getattr(p, "ip", "") == ip:
                if getattr(p, "user", ""):
                    target_user = p.user
                if getattr(p, "password", ""):
                    target_pass = p.password
                break
    except Exception:
        pass

    def do_ricoh_login():
        session.cookies.set("cookieOnOffChecker", "on")
        try:
            resp = session.get(urllib.parse.urljoin(base_url, "/web/entry/en/websys/webArch/authForm.cgi"), timeout=5)
            html = resp.text
            if "document.form1.submit()" in html or 'name="form1"' in html:
                fields = {}
                for m in re.finditer(r'<input\s+[^>]*?type\s*=\s*["\']?hidden["\']?[^>]*?>', html, re.I | re.S):
                    tag = m.group(0)
                    name_m = re.search(r'name\s*=\s*["\']?([^"\']+)["\']?', tag, re.I)
                    value_m = re.search(r'value\s*=\s*["\']?([^"\']*)["\']?', tag, re.I)
                    if name_m:
                        fields[name_m.group(1)] = value_m.group(1) if value_m else ""
                action_m = re.search(r'action\s*=\s*["\']([^"\']+)["\']', html, re.I)
                if action_m:
                    resp = session.post(urllib.parse.urljoin(resp.url, action_m.group(1)), data=fields, timeout=5)
                    html = resp.text

            # Robust wimToken parsing (handles any attribute order inside tag)
            wim_token = ""
            wim_token_m = re.search(r'wimToken\s*[:=]\s*["\']?([^"\'\s;>]+)["\']?', html, re.I)
            if wim_token_m:
                wim_token = wim_token_m.group(1)
            else:
                for tag_m in re.finditer(r'<input\s+[^>]*?>', html, re.I):
                    tag_str = tag_m.group(0)
                    if re.search(r'name\s*=\s*["\']?wimToken["\']?', tag_str, re.I):
                        val_m = re.search(r'value\s*=\s*["\']?([^"\']*)["\']?', tag_str, re.I)
                        if val_m:
                            wim_token = val_m.group(1)
                            break

            if not wim_token:
                return False

            enc_user = base64.b64encode(target_user.encode()).decode()
            pws = [target_pass] if target_pass else []
            for pw in pws + ["", "admin", "1234", "12345"]:
                enc_pass = base64.b64encode(pw.encode()).decode()
                strategies = [
                    ("/web/guest/en/websys/webArch/login.cgi",
                     {"userid": enc_user, "username": enc_user, "password": enc_pass, "wimToken": wim_token, "open": "websys/webArch/authForm.cgi"}),
                    ("/web/entry/en/websys/webArch/login.cgi",
                     {"userid": target_user, "username": target_user, "password": pw, "wimToken": wim_token}),
                ]
                for path, data in strategies:
                    try:
                        r = session.post(urllib.parse.urljoin(base_url, path), data=data, headers={"Referer": resp.url}, timeout=6)
                        wimsesid = session.cookies.get("wimsesid", "")
                        if wimsesid and wimsesid != "--" and "Login User Name" not in r.text:
                            return True
                    except:
                        pass
        except:
            pass
        return False

    if not req_path or req_path == "/" or req_path == "logout":
        if req_path == "logout":
            try:
                session.get(urllib.parse.urljoin(base_url, "/web/entry/en/websys/webArch/logout.cgi"), timeout=3)
                session.get(urllib.parse.urljoin(base_url, "/web/guest/en/websys/webArch/logout.cgi"), timeout=3)
            except:
                pass
            if hasattr(bridge, session_attr):
                delattr(bridge, session_attr)
            return {"html": "<html><body>Session Closed.</body></html>", "path": "/logout"}

        if is_ricoh:
            logged = do_ricoh_login()
            if logged:
                req_path = "/web/entry/en/websys/webArch/topPage.cgi"
            else:
                req_path = "/web/guest/en/websys/webArch/topPage.cgi"
        else:
            req_path = "/"

    target_url = urllib.parse.urljoin(base_url, req_path)

    post_data = None
    if method == "POST" and req_data_b64:
        try:
            decoded = base64.b64decode(req_data_b64.encode('utf-8')).decode('utf-8')
            post_data = json.loads(decoded)
        except:
            pass

    html = ""
    final_url = target_url
    for loop in range(4):
        try:
            if method == "POST" and post_data:
                resp = session.post(target_url, data=post_data, timeout=25)
            else:
                resp = session.get(target_url, timeout=25)
            final_url = resp.url
            html = resp.text
        except Exception as e:
            return {"error": f"Connection failed to {target_url}: {e}"}

        if any(ind in html for ind in ["Login User Name", "Login Password", "authForm.cgi"]):
            logged = do_ricoh_login()
            if logged:
                try:
                    resp = session.get(target_url, timeout=25)
                    final_url = resp.url
                    html = resp.text
                except Exception as e:
                    return {"error": f"Retry failed: {e}"}

        frames = re.findall(r'<frame\s+([^>]+)>', html, re.I)
        main_frame_src = None
        for frame_attr in frames:
            src_m = re.search(r'src=["\']([^"\']+)["\']', frame_attr, re.I)
            name_m = re.search(r'name=["\']([^"\']+)["\']', frame_attr, re.I)
            if src_m:
                src = src_m.group(1).strip()
                name = name_m.group(1).strip().lower() if name_m else ''
                if name in ['work', 'workframe', 'main', 'contents', 'toplevelframe', 'body', 'right'] or any(k in src.lower() for k in ['toppage', 'frameindex', 'login', 'index', 'main']):
                    main_frame_src = src
                    break
                if not main_frame_src:
                    main_frame_src = src

        if main_frame_src:
            target_url = urllib.parse.urljoin(final_url, main_frame_src)
            method = "GET"
            post_data = None
            continue

        break

    def inline_assets(html_content, current_url):
        urls_to_fetch = []
        entries = []

        # 1. Parse links
        links = re.findall(r'<link[^>]+>', html_content, re.I)
        for tag in links:
            href_m = re.search(r'href\s*=\s*["\']([^"\']+)["\']', tag, re.I)
            rel_m = re.search(r'rel\s*=\s*["\']stylesheet["\']', tag, re.I)
            if href_m and rel_m:
                href = href_m.group(1).strip()
                full_url = urllib.parse.urljoin(current_url, href)
                entries.append(('link', tag, full_url, href))
                urls_to_fetch.append(full_url)

        # 2. Parse script tags
        script_matches = re.finditer(r'<script[^>]+src\s*=\s*["\']([^"\']+)["\'][^>]*>(?:\s*</script>)?', html_content, re.I | re.S)
        for m in script_matches:
            tag = m.group(0)
            src = m.group(1).strip()
            if src.startswith('http') and not src.startswith(base_url):
                continue
            full_url = urllib.parse.urljoin(current_url, src)
            entries.append(('script', tag, full_url, src))
            urls_to_fetch.append(full_url)

        # 3. Parse generic images, backgrounds, buttons
        attr_matches = re.finditer(r'\b(src|background)\s*=\s*["\']([^"\']+)["\']', html_content, re.I)
        for m in attr_matches:
            tag = m.group(0)
            attr = m.group(1).lower()
            val = m.group(2).strip()

            if val.startswith('data:') or val.endswith('.js') or val.endswith('.css') or (val.startswith('http') and not val.startswith(base_url)):
                continue

            full_url = urllib.parse.urljoin(current_url, val)
            entries.append(('asset_attr', tag, full_url, (attr, val)))
            urls_to_fetch.append(full_url)

        # 4. Parse CSS url() functions inside HTML/styles
        url_matches = re.finditer(r'url\(\s*["\']?([^"\')]+)["\']?\s*\)', html_content, re.I)
        for m in url_matches:
            tag = m.group(0)
            val = m.group(1).strip()

            if val.startswith('data:') or (val.startswith('http') and not val.startswith(base_url)):
                continue

            full_url = urllib.parse.urljoin(current_url, val)
            entries.append(('asset_url', tag, full_url, val))
            urls_to_fetch.append(full_url)

        # Fetch in parallel
        fetched_content = {}
        def fetch_one(url):
            try:
                r = session.get(url, timeout=8.0)
                if r.status_code == 200:
                    return url, r.content, r.headers.get('Content-Type', '')
            except:
                pass
            return url, None, None

        if urls_to_fetch:
            with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
                futures = {executor.submit(fetch_one, url): url for url in urls_to_fetch}
                for fut in concurrent.futures.as_completed(futures):
                    url, content, mime = fut.result()
                    if content is not None:
                        fetched_content[url] = (content, mime)

        # Replace tags
        for etype, tag, url, extra in entries:
            if url in fetched_content:
                content, mime = fetched_content[url]
                if etype == 'link':
                    try:
                        text = content.decode('utf-8', errors='ignore')
                        html_content = html_content.replace(tag, f"<style>/* inlined {extra} */\n{text}\n</style>")
                    except:
                        pass
                elif etype == 'script':
                    try:
                        text = content.decode('utf-8', errors='ignore')
                        safe_js = text.replace('</script>', '<\\/script>')
                        html_content = html_content.replace(tag, f"<script>/* inlined {extra} */\n{safe_js}\n</script>")
                    except:
                        pass
                elif etype == 'asset_attr':
                    attr, orig_val = extra
                    if len(content) < 150000:
                        mime_type = mime or 'image/gif'
                        b64 = base64.b64encode(content).decode('utf-8')
                        new_src = f"data:{mime_type};base64,{b64}"
                        new_tag = tag.replace(orig_val, new_src, 1)
                        html_content = html_content.replace(tag, new_tag)
                elif etype == 'asset_url':
                    orig_val = extra
                    if len(content) < 150000:
                        mime_type = mime or 'image/gif'
                        b64 = base64.b64encode(content).decode('utf-8')
                        new_src = f"data:{mime_type};base64,{b64}"
                        new_tag = f"url({new_src})"
                        html_content = html_content.replace(tag, new_tag)
            else:
                if etype == 'link':
                    html_content = html_content.replace(tag, f"<!-- failed to inline stylesheet {extra} -->")
                elif etype == 'script':
                    html_content = html_content.replace(tag, f"<!-- failed to inline script {extra} -->")

        return html_content

    try:
        html = inline_assets(html, final_url)
    except Exception as e:
        pass

    # Fetch and inline Toshiba locale messages if this is a Toshiba page
    if not is_ricoh and "TopAccess" in html:
        try:
            loc_url = urllib.parse.urljoin(final_url, "/localization/en_US/locale_TopAccess_Messages.js")
            r_loc = session.get(loc_url, timeout=3.0)
            if r_loc.status_code == 200:
                loc_js = r_loc.text
                if "<head>" in html:
                    html = html.replace("<head>", "<head><script>/* inlined locale_TopAccess_Messages.js */\n" + loc_js + "\n</script>", 1)
                else:
                    html = "<script>/* inlined locale_TopAccess_Messages.js */\n" + loc_js + "\n</script>" + html
        except:
            pass

    parsed_final = urllib.parse.urlparse(final_url)
    final_path = parsed_final.path
    if parsed_final.query:
        final_path += "?" + parsed_final.query

    return {"html": html, "path": final_path}

try:
    res = run_scraper()
    context['result_payload'] = res
except Exception as e:
    context['result_payload'] = {'error': str(e)}
